import { useRef, useState } from "react";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { Download, FileText, History, Search, UploadCloud } from "lucide-react";
import { Card } from "@/components/ui/Card";
import { AppPageHero } from "@/components/app/AppPageHero";
import { Button } from "@/components/ui/Button";
import { StatusBadge } from "@/components/ui/StatusBadge";
import { portalRepository } from "@/services/supabase/portal";
import { analytics } from "@/services/analytics";
import { usePageMeta } from "@/hooks/usePageMeta";

export default function DocumentsPage() {
  usePageMeta("Documents", "Téléversez et suivez les versions conservées dans le stockage privé du projet.");
  const client = useQueryClient();
  const { data, isLoading, error } = useQuery({ queryKey: ["portal", "snapshot"], queryFn: portalRepository.getSnapshot });
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [query, setQuery] = useState("");
  const inputRef = useRef<HTMLInputElement>(null);
  const selected = data?.documents.find((document) => document.id === selectedId) ?? data?.documents[0] ?? null;
  const filtered = (data?.documents ?? []).filter((document) => `${document.label} ${document.category}`.toLocaleLowerCase("fr-FR").includes(query.toLocaleLowerCase("fr-FR")));
  const received = (data?.documents ?? []).filter((document) => !["required", "not_requested"].includes(document.status)).length;
  const upload = useMutation({ mutationFn: async (file: File) => { if (!data?.project || !selected) throw new Error("Sélectionnez une exigence documentaire."); return portalRepository.uploadDocument(data.project.id, selected.id, selected.documentId, file); }, onSuccess: async (result, file) => { analytics.track(result.demo ? "demo_document_selected" : "document_uploaded", { type: file.type, size: file.size }); await client.invalidateQueries({ queryKey: ["portal", "snapshot"] }); } });
  async function download() { if (!selected?.storagePath) return; const url = await portalRepository.createDocumentDownload(selected.storagePath); if (url) window.open(url, "_blank", "noopener,noreferrer"); }
  return <div className="mx-auto max-w-[1400px] space-y-5"><AppPageHero icon={FileText} eyebrow="Centre documentaire privé" title={<>Chaque pièce garde <span className="gradient-text">son statut et sa version.</span></>} description="Les fichiers connectés sont conservés dans un bucket privé. Le téléchargement utilise un lien signé de courte durée." stat={{ value: `${received}/${data?.documents.length ?? 0}`, label: "Pièces reçues" }} action={<><Button variant="dark" onClick={() => inputRef.current?.click()} disabled={!selected || upload.isPending}><UploadCloud className="size-4" />{upload.isPending ? "Téléversement…" : "Ajouter une version"}</Button><input ref={inputRef} type="file" hidden accept=".pdf,.png,.jpg,.jpeg,.webp" onChange={(event) => { const file = event.target.files?.[0]; if (file) upload.mutate(file); event.target.value = ""; }} /></>} />{error ? <Card className="p-5 text-[color:var(--blue)]">{error instanceof Error ? error.message : "Chargement impossible"}</Card> : null}{upload.error ? <Card className="border-[var(--blue)]/20 p-5 text-sm text-[color:var(--blue)]">{upload.error instanceof Error ? upload.error.message : "Téléversement impossible"}</Card> : null}{upload.isSuccess ? <Card className="border-[var(--mint)] bg-[var(--mint-soft)] p-4 text-sm font-semibold">La nouvelle version a été enregistrée et rattachée au projet.</Card> : null}<div className="grid gap-5 xl:grid-cols-[1.15fr_.85fr]"><Card className="overflow-hidden"><div className="flex flex-col gap-3 border-b border-[var(--line)] p-5 sm:flex-row sm:items-center sm:justify-between"><div><p className="text-xs font-semibold uppercase tracking-[.13em] text-[color:var(--muted)]">{data?.project?.displayName ?? "Projet"}</p><h2 className="mt-2 text-2xl font-semibold">Exigences documentaires</h2></div><label className="flex h-11 items-center gap-2 rounded-full border border-[var(--line)] bg-[var(--paper)] px-4 text-sm"><Search className="size-4 text-[color:var(--muted)]" /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Rechercher" className="w-36 bg-transparent outline-none" /></label></div><div className="divide-y divide-[var(--line)]">{filtered.map((document) => <button key={document.id} onClick={() => setSelectedId(document.id)} className={`flex w-full items-center gap-4 p-5 text-left transition ${selected?.id === document.id ? "bg-[var(--mint-soft)]/55" : "hover:bg-[var(--paper)]"}`}><span className="grid size-11 place-items-center rounded-[16px] bg-white shadow-sm"><FileText className="size-4" /></span><div className="min-w-0 flex-1"><p className="truncate font-semibold">{document.label}</p><p className="mt-1 text-xs text-[color:var(--muted)]">{document.category}{document.filename ? ` · ${document.filename}` : ""}</p></div><StatusBadge status={document.status} /></button>)}{!isLoading && filtered.length === 0 ? <p className="p-10 text-center text-sm text-[color:var(--muted)]">Aucune exigence disponible.</p> : null}</div></Card><div className="space-y-5"><Card className="p-6">{selected ? <><div className="flex items-start justify-between gap-4"><div><p className="text-[10px] font-bold uppercase tracking-[.13em] text-[color:var(--muted)]">Élément sélectionné</p><h2 className="mt-2 text-2xl font-semibold">{selected.label}</h2></div><StatusBadge status={selected.status} /></div>{selected.filename ? <div className="mt-6 rounded-[20px] bg-[var(--paper)] p-4"><p className="font-semibold">{selected.filename}</p><p className="mt-1 text-xs text-[color:var(--muted)]">{selected.mimeType} · {selected.sizeBytes ? `${(selected.sizeBytes / 1_048_576).toFixed(2)} Mo` : "taille inconnue"}</p></div> : <div className="mt-6 rounded-[20px] border border-dashed border-[var(--line)] p-6 text-center text-sm text-[color:var(--muted)]">Aucune version transmise.</div>}{selected.comment ? <div className="mt-4 rounded-[20px] border border-[var(--blue)]/20 bg-[var(--blue)]/8 p-4"><p className="text-xs font-bold text-[color:var(--blue)]">Retour de contrôle</p><p className="mt-2 text-sm leading-6">{selected.comment}</p></div> : null}<div className="mt-5 grid gap-2 sm:grid-cols-2"><Button onClick={() => inputRef.current?.click()}><UploadCloud className="size-4" />Nouvelle version</Button><Button variant="secondary" onClick={() => void download()} disabled={!selected.storagePath}><Download className="size-4" />Télécharger</Button></div></> : <p className="text-sm text-[color:var(--muted)]">Sélectionnez un document.</p>}</Card><Card className="p-6"><div className="flex items-center gap-3"><History className="size-5 text-[color:var(--blue)]" /><h3 className="font-semibold">Traçabilité</h3></div><p className="mt-3 text-sm leading-6 text-[color:var(--muted)]">Chaque nouveau fichier crée une version distincte. Les validations et demandes de correction passent par une opération serveur auditée.</p></Card></div></div></div>;
}
